47	// Re-validate the (possibly user-edited) tags and insert the item.
48	export async function confirmItem(input: {
49	  imagePath: string;
50	  cutoutPath: string;
51	  name?: string | null;
52	  brand?: string | null;
53	  tags: unknown;
54	}) {
55	  const supabase = await createClient();
56	  const {
57	    data: { user },
58	  } = await supabase.auth.getUser();
59	  if (!user) throw new Error("Not authenticated");
60	
61	  const tags = TagSchema.parse(input.tags);
62	  const row = {
63	    ...tagsToItemRow({
64	      userId: user.id,
65	      imageUrl: input.imagePath,
66	      cutoutUrl: input.cutoutPath,
67	      tags,
68	    }),
69	    name: input.name ?? tags.subcategory,
70	    brand: input.brand ?? null,
71	  };
72	  const { error } = await supabase.from("items").insert(row);
73	  if (error) throw error;
74	  revalidatePath("/closet");
75	}
