4	import { processImage, blobToBase64 } from "@/lib/images/process";
5	import { uploadAndTag, confirmItem } from "@/app/closet/upload/actions";
6	import type { Tags } from "@/lib/ai/tagging-schema";
7	
8	export type Draft = {
9	  imagePath: string;
10	  cutoutPath: string;
11	  cutoutUrl: string;
12	  name: string;
13	  brand: string;
14	  tags: Tags;
15	};
