17	export type CapturePhase = "aim" | "removing" | "confirm";
18	
19	export function useCapture(options?: { onSaved?: () => void }) {
20	  const [phase, setPhase] = useState<CapturePhase>("aim");
21	  const [draft, setDraft] = useState<Draft | null>(null);
22	  const [error, setError] = useState<string | null>(null);
23	  const [saving, setSaving] = useState(false);
24	
25	  // Free the object URL when it's replaced by a new capture or on unmount.
26	  useEffect(() => {
27	    const url = draft?.cutoutUrl;
28	    return () => {
29	      if (url) URL.revokeObjectURL(url);
30	    };
31	  }, [draft?.cutoutUrl]);
32	
33	  async function capture(file: File) {
34	    setError(null);
35	    setPhase("removing");
36	    try {
37	      const { original, cutout, cutoutMediaType } = await processImage(file);
38	      const [originalB64, cutoutB64] = await Promise.all([
39	        blobToBase64(original),
40	        blobToBase64(cutout),
41	      ]);
42	      const res = await uploadAndTag({ originalB64, cutoutB64, mediaType: cutoutMediaType });
43	      setDraft({
44	        imagePath: res.imagePath,
45	        cutoutPath: res.cutoutPath,
46	        cutoutUrl: URL.createObjectURL(cutout),
47	        name: res.tags.subcategory,
48	        brand: "",
49	        tags: res.tags,
50	      });
51	      setPhase("confirm");
52	    } catch (e) {
53	      setError(e instanceof Error ? e.message : "Capture failed");
54	      setPhase("aim");
55	    }
56	  }
57	
58	  function updateDraft(patch: Partial<Draft>) {
59	    setDraft((d) => (d ? { ...d, ...patch } : d));
60	  }
61	
62	  function updateTags(patch: Partial<Tags>) {
63	    setDraft((d) => (d ? { ...d, tags: { ...d.tags, ...patch } } : d));
64	  }
65	
66	  function toggleSeason(s: Tags["seasons"][number]) {
67	    setDraft((d) => {
68	      if (!d) return d;
69	      const cur = d.tags.seasons;
70	      const next = cur.includes(s) ? cur.filter((x) => x !== s) : [...cur, s];
71	      return next.length ? { ...d, tags: { ...d.tags, seasons: next } } : d;
72	    });
73	  }
74	
75	  async function save() {
76	    if (!draft) return;
77	    setSaving(true);
78	    setError(null);
79	    try {
80	      await confirmItem({
81	        imagePath: draft.imagePath,
82	        cutoutPath: draft.cutoutPath,
83	        name: draft.name || null,
84	        brand: draft.brand || null,
85	        tags: draft.tags,
86	      });
87	      options?.onSaved?.();
88	      setDraft(null);
89	      setPhase("aim");
90	    } catch (e) {
91	      setError(e instanceof Error ? e.message : "Save failed");
92	    } finally {
93	      setSaving(false);
94	    }
95	  }
96	
97	  return { phase, draft, error, saving, capture, updateDraft, updateTags, toggleSeason, save };
98	}
